function renderRecords(){
 const groups=[['problem',problemCard,'Open each problem statement to read its full scope and guide decision. Green is approved, red needs revision, yellow is awaiting review, and grey is a retained historical draft.'],['search',searchCard,'Open a search to see its keywords, date, notes and Scholar link.'],['paper',paperCard,'Open a paper to see its source links, screening reason and full publication details.'],['review',reviewCard,'Select a paper to view its full evidence. Green is approved, red needs revision, yellow is awaiting guide review, and grey means the student is still reading.'],['gap',gapCard,'Open a synthesis to compare the evidence and read the guide decision. Red entries must be corrected and resubmitted.'],['methodology',methodologyCard,'Open the methodology package to review the proposed system, data controls, baselines, evaluation and guide decision. Red entries require revision; yellow entries await review.'],['setup',setupCard,'Use one workspace record for the approved method, team repository, exact checkpoint, repeatable environment and evidence folder.'],['publication',publicationCard,'One team record makes the paper claim, closest-paper comparison, claim limits and reproducibility evidence reviewable. The guide verifies novelty and reproducibility separately.'],['draft',draftCard,'Use one tracker record per paper section. Prepare introduction, related work and methodology now; submit results, discussion and conclusion after the evidence is ready.'],['interaction',interactionCard,'Open an interaction to read the discussion, participants and next actions.']];
 groups.splice(groups.length-1,0,['result',resultCard,'Open evidence and individual analyses, then the final team synthesis. Guide feedback remains visible after resubmission.']);
 $('#records').innerHTML=groups.map(([kind,card,help])=>{const rows=shared[definitions[kind].collection]||[];return `<details ${['problem','paper','review','methodology','setup','result'].includes(kind)?'open':''}><summary>${esc(definitions[kind].title)} (${rows.length})</summary><p class="helper review-list-help">${esc(help)}</p><div class="review-list">${rows.length?rows.map(card).join(''):'<p>No shared records yet.</p>'}</div></details>`;}).join('');
 const old=(legacy.papers||[]).filter(p=>p.projectId===team.id);
 if(old.length)$('#records').insertAdjacentHTML('beforeend',`<details><summary>Earlier browser drafts (${old.length})</summary><p>Check shared records for duplicates before submitting.</p>${old.map((p,i)=>`<p>${esc(p.title)} <button data-legacy="${i}" type="button">Review old draft</button></p>`).join('')}</details>`);
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openRecord(b.dataset.edit,shared[definitions[b.dataset.edit].collection][Number(b.dataset.index)]));
 document.querySelectorAll('[data-legacy]').forEach(b=>b.onclick=()=>{const p=old[Number(b.dataset.legacy)];renderForm('paper',{...p,id:crypto.randomUUID(),authors:p.authorYear,status:'Screened',revision:0});});
}
function setGuideView(enabled){guideView=enabled;document.body.classList.toggle('guide-view',enabled);}
async function request(action,payload,projectId=team.id,codeOverride=''){
 const accessCode=codeOverride||(guideView?guideAccessCode:sessionStorage.getItem('capstone-code:'+projectId))||'';if(!accessCode)throw new Error('Enter your team access code or guide key and load shared records first.');
 for(let attempt=0;attempt<2;attempt++){
  const response=await fetch(API,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,projectId,accessCode,payload}),signal:AbortSignal.timeout(60000)});
  const body=await response.text();let result;
  try{result=JSON.parse(body.replace(/^\uFEFF/,'').trim());}
  catch(error){
   if(attempt===0){await new Promise(resolve=>setTimeout(resolve,600));continue;}
   const temporaryPage=/<(?:!doctype|html|body)\b/i.test(body);
   throw new Error(temporaryPage?'The tracker service temporarily returned a web page instead of team data. Please wait a minute, then load shared records again.':'The tracker service returned an unreadable response. Please try loading shared records again.');
  }
  if(!response.ok)throw new Error(result.error||'The tracker service could not complete this request.');
  if(action==='saveResult'&&result.ok&&!result.capabilities?.includes('results-v1'))throw new Error('Result workflow deployment is not ready. Your draft is retained.');
  if(!result.ok)throw new Error(result.error||'Could not save.');if(result.version!==3)throw new Error('Backend needs the research-workflow update.');return result;
 }
}
function setBusy(value){busy=value;document.querySelectorAll('button,input,select,textarea').forEach(b=>b.disabled=value);}
$('#connect-form').onsubmit=async e=>{
 e.preventDefault();const enteredCode=$('#access-code').value.trim();setBusy(true);setMessage('#connection-message','Loading shared team records…');
 try{const r=await request('loadProject',null,team.id,enteredCode);setGuideView(!!r.readOnly);guideAccessCode=r.readOnly?enteredCode:'';if(r.readOnly)$('#access-code').value='';else sessionStorage.setItem('capstone-code:'+team.id,enteredCode);shared=r.data;connected=true;updateProgress();renderRecords();renderForm(activeKind);setMessage('#connection-message',r.readOnly?'Guide view · read-only. Select another project to inspect its records.':'Connected. Displaying confirmed records from Google Sheets.');}
 catch(error){connected=false;setGuideView(false);guideAccessCode='';updateProgress();setMessage('#connection-message',error.message);}finally{setBusy(false);}
};
$('#research-form').onsubmit=async e=>{
 e.preventDefault();if(guideView){setMessage('#save-message','Guide view is read-only. Use the tracker for approval and feedback.');return;}const kind=activeKind,p=formData(),projectId=team.id;saveDraft(kind,p);
 if(kind==='methodology'&&p.submissionType==='Final Team Version'&&!String(p.comparison||'').trim()){setMessage('#save-message','Explain what was kept or changed from both individual drafts before submitting the final team version.');return;}
 setBusy(true);setMessage('#save-message','Saving and waiting for confirmation…');
 try{const r=await request(definitions[kind].action,p,projectId);shared=r.data;connected=true;p.revision=r.record.Revision;saveDraft(kind,p);updateProgress();renderRecords();renderForm(kind,p);if(['review','problem','gap','methodology','setup','result','publication','draft'].includes(kind)){const collection=shared[definitions[kind].collection],idColumn=definitions[kind].idColumn,record=collection.find(row=>row[idColumn]===p.id);showGuideNotice(record,guideRecordLabel(kind));}setMessage('#save-message','Saved and confirmed in Google Sheets.');setMessage('#connection-message','Connected. Shared records are up to date.');}
 catch(error){setMessage('#save-message','Draft retained on this device. Save not confirmed: '+error.message);}finally{setBusy(false);}
};
$('#team-selector').onchange=async e=>{team=teams.find(t=>t.id===e.target.value);shared=emptyData();connected=false;setMessage('#save-message','');updateProgress();renderRecords();renderForm('problem');if(guideView&&guideAccessCode){setBusy(true);setMessage('#connection-message','Loading guide view…');try{const r=await request('loadProject');shared=r.data;connected=true;updateProgress();renderRecords();setMessage('#connection-message','Guide view · read-only. Select another project to inspect its records.');}catch(error){setMessage('#connection-message',error.message);}finally{setBusy(false);}}else{$('#access-code').value=sessionStorage.getItem('capstone-code:'+team.id)||'';setMessage('#connection-message','Load this team’s shared records.');}};
$('#lock-team').onclick=()=>{if(!guideView)sessionStorage.removeItem('capstone-code:'+team.id);guideAccessCode='';setGuideView(false);$('#access-code').value='';shared=emptyData();connected=false;updateProgress();renderRecords();setMessage('#connection-message','Session locked. Local form drafts remain on this device.');};
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{renderForm(b.dataset.step);setMessage('#save-message','');});
$('#export-review').onclick=()=>{
 const columns=['Paper ID','Project ID','Author','Year','Research Task','Algorithm or Method','Dataset','Metrics','Result','Limitations','Research Gap','Reviewer','Review Status','Guide Approval','Guide Feedback'];
 const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';
 const csv=[columns,...shared.reviews.map(r=>columns.map(c=>r[c]))].map(r=>r.map(cell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=team.id+'-literature-review.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
};
